<?php
declare(strict_types=1);
function databaseConfig(): array {$f=[];$p=__DIR__.'/config/database.php';if(is_file($p)){$v=require $p;if(is_array($v))$f=$v;}return ['host'=>getenv('DB_HOST')?:($f['host']??'localhost'),'port'=>(int)(getenv('DB_PORT')?:($f['port']??3306)),'name'=>getenv('DB_NAME')?:($f['name']??''),'user'=>getenv('DB_USER')?:($f['user']??''),'password'=>getenv('DB_PASSWORD')?:($f['password']??'')];}
function database(): PDO {static $db=null;if($db instanceof PDO)return $db;$c=databaseConfig();if($c['name']===''||$c['user']==='')throw new RuntimeException('قاعدة البيانات غير مضبوطة. انسخ config/database.example.php إلى config/database.php ثم أدخل بيانات MySQL.');$dsn=sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$c['host'],$c['port'],$c['name']);$db=new PDO($dsn,$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_STRINGIFY_FETCHES=>false]);return $db;}
